add('hanzhong','梁州以南郑为治所，618年设置总管府，天宝时称汉中郡，是汉中地区的军政中心。784年升为兴元府，官员资序比照京兆、河南二府，显示其在唐中期政治格局中地位的变化。',BS,'755年为汉中郡，治南郑；梁州、短暂的褒州和784年后的兴元府属于不同时段。',[
 q(B39,'武德元年，置梁州總管府，管梁、洋、集、興四州。','618年汉中区域军政中心。'),q(B39,'天寶元年，改為漢中郡，仍為都督府。乾元元年，復為梁州。興元元年六月，昇為興元府。官員資序，一切同京兆、河南二府。','755年名和784年升府，避免现代百科错误的874年。'),q(B39,'南鄭州 所理。漢縣，屬漢中郡。','南郑为治所；保留原文分词。')],name='梁州',modern='陕西汉中地区',coord_title='汉中市',snapshot_name='汉中郡',aliases=['梁州','汉中','南郑','褒州','兴元府'])
add('kuizhou','夔州由唐初信州改名，治所地区对应今奉节，曾作为统摄峡江诸州的总管、都督中心。649年人复县改称奉节，742年州改云安郡；州域内云安县设盐官，也说明这里的行政、交通与盐业联系。',BS,'755年为云安郡，治奉节县；云安郡名不意味着郡治在辖下云安县，奉节古今县城也有迁移。',[
 q(B39,'又改信州為夔州，仍置總管，管夔、硤、施、業、浦、涪、渝、谷、南、智、務、黔、克、思、巫、平十九州。','唐初夔州的区域总管职能。'),q(B39,'天寶元年，改為雲安郡。','755年云安郡。'),q(B39,'貞觀二十三年，改為奉節','649年县名节点。'),q(B39,'雲安 漢朐䏰縣，屬巴郡。故城曰萬戶城。縣西三十里，有鹽官','所辖云安县的盐官，不误作奉节城区设施。')],name='夔州',modern='重庆奉节地区',coord_title='奉节县',snapshot_name='云安郡',aliases=['夔州','奉节','人复','信州'],location_note='古今奉节县城多次迁移，现代县域点不核定唐城城址。')
add('yuzhou-chongqing','渝州在618年沿用隋代州名，以巴县为州治，是今重庆城区一带的地方行政中心。唐初州县反复分合，639年南平县划入，742年改南平郡，乾元初恢复渝州；“重庆”名称则属于宋代之后。',BS,'755年为南平郡，治巴县；渝州与辖下南平县是不同层级。',[
 q(B39,'武德元年，置渝州，因開皇舊名','618年置渝州。'),q(B39,'貞觀十三年，以廢霸州之南平縣來屬。天寶元年，改為南平郡。乾元初，復為渝州。','639年行政调整和755年郡名。'),q('yuzhou-prefecture','治所在巴县（今重庆市）。','巴县治所与现代重庆地区对应。')],name='渝州',modern='重庆主城地区',coord_title='Chongqing',snapshot_name='南平郡',aliases=['渝州','巴县','重庆'])
add('langzhou','阆州治阆中，唐初称隆州，712年改称阆州，天宝时改阆中郡。城市三面环阆水，承担川北州郡行政中心职能；唐代当地丝绸列入宫廷贡品，提供了理解区域手工业的一条线索。',BS,'755年为阆中郡，治阆中县；阆州、隆州为先后州名，区别于湖南朗州。',[
 q('langzhou-prefecture','唐玄宗先天元年（712年），改为阆州','采用专门州条目与旧唐书先天元年相互核对。'),q(B41,'天寶元年，改為閬中郡。乾元元年，復為閬州。','755年正式名称。'),q(B41,'皆治閬中。閬水迂曲經郡三面，故曰閬中','治所及水系关系。'),q('langzhong','唐代，阆中丝绸为宫廷贡品。','唐代丝绸贡赋。')],name='阆州',modern='四川南充阆中地区',coord_title='Langzhong',snapshot_name='阆中郡',aliases=['阆州','隆州','阆中'])
add('suizhou-suining','遂州在618年置州，治方义县，619年设置总管府，曾统管遂、梓、资、普等州。其都督职能后来数度设罢，742年改遂宁郡、758年复名遂州，体现川中城市行政地位并非始终固定。',BS,'755年为遂宁郡，治方义县；遂州与湖北随州的字形、地点均不同。',[
 q(B41,'武德元年，改為遂州，領方義、長江、青石三縣。二年，置總管府，管遂、梓、資、普四州。','618和619年的州与总管职能。'),q(B41,'十年，復置都督，督遂、果、普、合四州。十七年，罷都督府。天寶元年，改為遂寧郡。乾元元年，復為遂州。','贞观间都督设罢、755年郡名。'),q('suizhou-prefecture','治所在方义县（今四川省遂宁市）。','方义治所的现代地区对应。')],name='遂州',modern='四川遂宁地区',coord_title='遂宁市',snapshot_name='遂宁郡',aliases=['遂州','遂宁','方义'])
add('guizhou-guilin','桂州在621年置总管府，治临桂，承担桂北及附近地区的军政统摄职能。755年为始安郡，757年改建陵郡，758年复为桂州；692年修筑的相思埭又把这里与柳州方向水运联系起来。',LN,'755年为始安郡，治临桂；757年的建陵郡是后续名。“桂州”不是现代贵州省。',[
 q(B41,'武德四年，平蕭銑，置桂州總管府','621年桂州总管府。'),q(B41,'天寶元年，改為始安郡，依舊都督府。至德二年九月，改為建陵郡。乾元元年，復為桂州','742、757、758连续名称变化。'),q(B41,'臨桂 州所治。','临桂为州治。'),q('guilin','（692年）筑相思埭，即今桂柳运河。','692年水利工程的地区联系。')],name='桂州',modern='广西桂林地区',coord_title='桂林市',snapshot_name='始安郡',aliases=['桂州','桂林','临桂','建陵郡'],location_note='现代桂林行政参考点不核定唐临桂县治。')
add('liuzhou','柳州治马平县，621年先置昆州、634年改柳州，天宝时称龙城郡。唐代桂州经柳州至邕州的买马路，以及桂柳水路的开发，使这座地方行政中心也成为岭南内陆交通网络的一环。',LN,'755年为龙城郡，治马平县；早期昆州、南昆州与后来柳州属先后沿革。',[
 q(B41,'武德四年，平蕭銑，置昆州，領馬平、新平、文安、賀水、歸德五縣。','621年昆州建置。'),q(B41,'八年，改南昆為柳州。','承接贞观年号，634年柳州命名。'),q(B41,'馬平 州所治。','马平为柳州治所。'),q(B41,'天寶元年，改為龍城郡。乾元元年，復為柳州','755年龙城郡。'),q('liuzhou','唐太宗时期，开通了桂州经现在柳州到邕州的买马路','唐代陆路交通联系。'),q('liuzhou','武则天时期又在临桂相思埭开辟了桂柳运河，沟通湘江经漓江、洛清江到柳州的水路。','唐代区域水运，非精确复原线路。')],name='柳州',modern='广西柳州地区',coord_title='柳州市',snapshot_name='龙城郡',aliases=['柳州','马平','昆州','南昆州'])
add('yongzhou-nanning','邕州治宣化县，前身为622年设置的南晋州，天宝时称朗宁郡。城市承担桂西南地方军政中心的职能；822年再次设置经略使并由刺史兼任，显示中晚唐对这一地区防务的重新组织。',LN,'755年为朗宁郡，治宣化县；邕州与今湖南永州不可混淆。',[
 q(B41,'武德五年，置南晉州，領宣化一縣。','622年南晋州前身。'),q(B41,'天寶元年改為朗寧郡。乾元元年復為邕州。','755年郡名。'),q(B41,'長慶二年六月，復置經略使，以刺史領之。刺史充經略使，管戍兵一千七百人','822年经略使与防务职能，不将兵数当作全城人口。'),q(B41,'宣化 州所治。','宣化县为治所。')],name='邕州',modern='广西南宁地区',coord_title='南宁市',snapshot_name='朗宁郡',aliases=['邕州','南晋州','宣化','南宁'])
add('annan-songping','交州都督府在679年改为安南都护府，治宋平县，对应今越南河内地区。866年唐朝收复府治后设置静海军，高骈营建大罗城并疏浚江道；都护府、驻军和城址变化须按时段阅读。',SW,'755年为安南都护府，治宋平；757年改镇南、766年恢复安南，大罗城营建为866年后的节点。',[
 q(B41,'調露元年八月，改交州都督府為安南都護府。','679年安南都护府名称。'),q('annan-protectorate','治所位于宋平县（今越南河内），由交州刺史充任都护。','宋平治所及军政管理。'),q('annan-protectorate','唐肃宗至德二年（757年），改名镇南都护府，唐代宗永泰二年（766年），复名安南都护府。','757和766名称变化。'),q('hanoi','咸通七年（866年），安南都护经略招讨使高骈收复安南。朝廷以安南都护府置靜海軍节度使，令高骈以节度使身份镇守安南。高骈随即兴建大罗城，并疏浚江道。','866年后的静海军与城市营建。')],name='安南府',modern='越南河内地区',coord_title='Hanoi',snapshot_name='安南都护府',aliases=['交州','安南府','宋平','大罗城','河内'],location_note='宋平、后来的大罗城及现代河内的城域不能据此视为完全重合。',political='唐代都护府治所，唐后期曾被南诏攻占又由唐收复；不表示整个618—907年始终稳定管辖。')
add('changzhou','常州在620年设置，州治在唐初移到晋陵地区，成为苏南州县的行政中心。625年武进县并入晋陵，742年州改晋陵郡、758年再称常州；州名、郡名与治所县名共同构成城市沿革。',JH,'755年为晋陵郡，治晋陵县；常州州名不应和早期曾作州治的常熟县混同。',[
 q(B40,'武德三年，杜伏威歸化，置常州，領晉陵、義興、無錫、武進四縣。','620年州县组织。'),q(B40,'八年，州廢，義興來屬，省武進入晉陵。天寶元年，改為晉陵郡。乾元元年，復為常州。','625年县调整与755年郡名。'),q(B40,'隋省郡，於常熟縣置常州。武德中，移於今治','唐初州治移到晋陵，区别早期常熟治所。')],name='常州',modern='江苏常州地区',coord_title='常州市',snapshot_name='晋陵郡',aliases=['常州','晋陵','毗陵'])

